window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-32326ea0e9253bbb"]={"versions": [{"id": "FIG-32326ea0e9253bbb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Statusautomaten <code>PackageManagerStatus</code>.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Funktionales Cluster <strong>Update and Configuration Management (UCM)</strong> (definiert in <code>AUTOSAR_SWS_UpdateAndConfigManagement</code> sowie <code>AUTOSAR_EXP_PlatformDesign</code>, Kapitel 13).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Lebenszyklus und der Transaktionszustände des Package Managers während der Verarbeitung, Validierung, Aktivierung, Verifikation und Bereinigung von Software-Paketen (Software Packages bzw. Software Cluster). Das Modell bildet die deterministische Grundlage für OTA-Updates (Over-the-Air), Felddiagnose und A/B-Partitionsswaps inklusive standardisierter Rollback-Pfade.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände (States):</strong></li>\n<li><code>IDLE</code>: Ruhezustand des Package Managers; keine aktive Update-Transaktion.</li>\n<li><code>PROCESSING</code>: Zustand der Paketextraktion, Signaturvalidierung und Artefakt-Vorbereitung (Aktivität: <code>do / process SW package</code>).</li>\n<li><code>READY</code>: Mindestens ein Paket ist erfolgreich verarbeitet und staged; System ist bereit für weitere Pakete oder Aktivierung.</li>\n<li><code>ACTIVATING</code>: Physische Vorbereitung der Ausführung (z. B. Mounten, Partitionsumschaltung, Link-Aktualisierung; Aktivität: <code>do / DependencyCheck</code>).</li>\n<li><code>VERIFYING</code>: Post-Aktivierungsphase zur Überprüfung der Systemstabilität und Prozessfunktionalität (Aktivität: <code>do / MonitorApplicationRestart</code>).</li>\n<li><code>ACTIVATED</code>: Software erfolgreich aktiviert und verifiziert, wartet auf finalen Commit.</li>\n<li><code>ROLLING-BACK</code>: Wiederherstellung des vorherigen konsistenten Systemzustands bei Fehler oder Abbruch (Aktivität: <code>do / roll back to old version</code>).</li>\n<li><code>ROLLED-BACK</code>: Rollback-Vorgang abgeschlossen; System befindet sich wieder auf dem Altstand.</li>\n<li><code>CLEANING_UP</code>: Freigabe temporärer Speicherbereiche, Löschung alter Artefakte oder abgebrochener Pakete (Aktivität: <code>do / clean up</code>).</li>\n<li><code>Initial</code>: Start-Pseudozustand.</li>\n<li><strong>Guards & Zustandsvariablen:</strong></li>\n<li><code>ProcessedPackages</code>: Zähler für erfolgreich verarbeitete Software-Pakete innerhalb der laufenden Session.</li>\n<li>Bedingungen: <code>[ProcessedPackages=0]</code> vs. <code>[ProcessedPackages&gt;0]</code>.</li>\n<li><strong>Schnittstellen & Service-Methoden (ara::ucm::PackageManagement):</strong></li>\n<li>Methoden/Trigger: <code>ProcessSwPackage</code>, <code>Cancel</code>, <code>Cancelled</code>, <code>PackageProcessed</code>, <code>RevertProcessedSwPackages</code>, <code>Activate</code>, <code>OnSuccess</code>, <code>OnFailure</code>, <code>Rollback</code>, <code>Finish</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Staging & Paketverarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt aus <code>IDLE</code> nach <code>PROCESSING</code> via Methodenaufruf <code>ProcessSwPackage</code>.</li>\n<li>Bei Abbruch ohne verarbeitete Pakete (<code>Cancelled [ProcessedPackages=0]</code>) Rückkehr nach <code>IDLE</code>.</li>\n<li>Bei erfolgreichem Abschluss oder Abbruch mit bereits persistierten Teilpaketen (<code>Cancelled, PackageProcessed [ProcessedPackages&gt;0]</code>) Übergang nach <code>READY</code>.</li>\n<li>Aus <code>READY</code> können sequenziell weitere Pakete verarbeitet werden (<code>ProcessSwPackage</code> $\\rightarrow$ <code>PROCESSING</code> $\\rightarrow$ <code>READY</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruch vor Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sowohl aus <code>PROCESSING</code> als auch aus <code>READY</code> verwirft <code>RevertProcessedSwPackages</code> alle gepufferten Pakete und wechselt nach <code>CLEANING_UP</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Verifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>READY</code> initiiert <code>Activate</code> den Übergang nach <code>ACTIVATING</code>.</li>\n<li>Während <code>ACTIVATING</code> wird <code>DependencyCheck</code> ausgeführt:</li>\n<li>Bei Fehler (<code>OnFailure</code>) fällt das System nicht-destruktiv nach <code>READY</code> zurück.</li>\n<li>Bei Erfolg (<code>OnSuccess</code>) erfolgt der Übergang nach <code>VERIFYING</code>.</li>\n<li>In <code>VERIFYING</code> überwacht <code>MonitorApplicationRestart</code> den deterministischen Hochlauf der Executables über den Execution Manager (EM):</li>\n<li>Bei erfolgreicher Quittierung (<code>OnSuccess</code>): Übergang nach <code>ACTIVATED</code>.</li>\n<li>Bei Fehlschlag (<code>OnFailure</code>) oder externem Abbruch (<code>Rollback</code>): Übergang nach <code>ROLLING-BACK</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rollback & Commit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>ACTIVATED</code> kann weiterhin ein <code>Rollback</code> angefordert werden (z. B. durch State Management bei Funktionsausfall im Feld).</li>\n<li><code>ROLLING-BACK</code> führt <code>do / roll back to old version</code> aus und geht per Completion-Transition nach <code>ROLLED-BACK</code> über.</li>\n<li>Sowohl der Erfolgszustand <code>ACTIVATED</code> als auch der Fehlerzustand <code>ROLLED-BACK</code> werden über den Trigger <code>Finish</code> nach <code>CLEANING_UP</code> überführt.</li>\n<li>Nach Abschluss von <code>do / clean up</code> schließt eine Completion-Transition den Zyklus zurück nach <code>IDLE</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Transaktionale Kapselung & A/B-Partitionierung:</strong> Bis zum Erreichen von <code>ACTIVATING</code> verbleibt das aktive Root-Dateisystem unberührt. Vorbereitung und Dependency-Checks geschehen strikt im Staging-/Inaktiv-Bereich.</li>\n<li><strong>Point-of-No-Return (<code>Finish</code>):</strong> Der Aufruf von <code>Finish()</code> aus <code>ACTIVATED</code> schließt die Update-Transaktion endgültig ab. In <code>CLEANING_UP</code> werden Fallback-Daten gelöscht. Ein Zurückrollen auf die vorherige Softwareversion ist danach nicht mehr über dieselbe UCM-Transaktion möglich, sondern erfordert ein eigenständiges Downgrade-Paket.</li>\n<li><strong>Zusammenspiel UCM $\\leftrightarrow$ Execution Management (EM) $\\leftrightarrow$ State Management (SM):</strong></li>\n<li>In der Phase <code>VERIFYING</code> müssen gestartete Applikationen ihren Ausführungsstatus via <code>ara::exec::ExecutionClient::ReportExecutionState()</code> melden.</li>\n<li>Das State Management bzw. der Platform Health Manager (PHM) entscheidet, ob <code>OnSuccess</code> vorliegt oder die UCM-Methode <code>Rollback()</code> getriggert werden muss.</li>\n<li><strong>API-Vertrag (<code>ara::com</code>):</strong> Die Transitionen korrespondieren direkt mit den asynchronen Methoden des <code>ara::ucm::PackageManagement</code>-Service-Interfaces. Methoden wie <code>ProcessSwPackage()</code>, <code>Activate()</code>, <code>Rollback()</code> und <code>Finish()</code> liefern <code>ara::core::Future</code> zurück; Clients müssen Statusabfragen (<code>GetStatus()</code>) synchronisieren oder Zustandsänderungs-Events abonnieren.</li>\n</ul>"}, {"id": "FIG-756595c0fdad7d52", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des Statusautomaten <code>PackageManagerStatus</code>.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Funktionales Cluster <strong>Update and Configuration Management (UCM)</strong> (definiert in <code>AUTOSAR_SWS_UpdateAndConfigManagement</code> sowie <code>AUTOSAR_EXP_PlatformDesign</code>, Kapitel 13).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Lebenszyklus und der Transaktionszustände des Package Managers während der Verarbeitung, Validierung, Aktivierung, Verifikation und Bereinigung von Software-Paketen (Software Packages bzw. Software Cluster). Das Modell bildet die deterministische Grundlage für OTA-Updates (Over-the-Air), Felddiagnose und A/B-Partitionsswaps inklusive standardisierter Rollback-Pfade.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände (States im Enumerator <code>PackageManagerStatusType</code>):</strong></li>\n<li><code>kIdle</code>: Ruhezustand des Package Managers; keine aktive Update-Transaktion.</li>\n<li><code>kProcessing</code>: Zustand der Paketextraktion, Signaturvalidierung und Artefakt-Vorbereitung (Aktivität: <code>do / process SW package</code>).</li>\n<li><code>kReady</code>: Mindestens ein Paket ist erfolgreich verarbeitet und staged; System ist bereit für weitere Pakete oder Aktivierung.</li>\n<li><code>kActivating</code>: Physische Vorbereitung der Ausführung (z. B. Partitionsumschaltung, Aktivität: <code>do / DependencyCheck</code>).</li>\n<li><code>kVerifying</code>: Post-Aktivierungsphase zur Überprüfung der Systemstabilität und Prozessfunktionalität (Aktivität: <code>do / MonitorApplicationRestart</code>).</li>\n<li><code>kActivated</code>: Software erfolgreich aktiviert und verifiziert, wartet auf finalen Commit.</li>\n<li><code>kRollingBack</code>: Wiederherstellung des vorherigen konsistenten Systemzustands bei Fehler oder Abbruch (Aktivität: <code>do / roll back to old version</code>).</li>\n<li><code>kRollingBackFailed</code>: Fehlerzustand, falls die Rollback-Operation selbst fehlschlägt.</li>\n<li><code>kRolledBack</code>: Rollback-Vorgang erfolgreich abgeschlossen; System befindet sich wieder auf dem Altstand.</li>\n<li><code>kCleaningUp</code>: Freigabe temporärer Speicherbereiche, Löschung alter Artefakte oder bereinigter Pakete (Aktivität: <code>do / clean up</code>).</li>\n<li><code>Initial</code>: Start-Pseudozustand.</li>\n<li><strong>Guards & Zustandsvariablen:</strong></li>\n<li><code>ProcessedPackages</code>: Zähler für verarbeitete Software-Pakete.</li>\n<li>Bedingungen: <code>[ProcessedPackages=0]</code> vs. <code>[ProcessedPackages&gt;0]</code>.</li>\n<li><strong>Schnittstellen & Service-Methoden (ara::ucm::PackageManagement):</strong></li>\n<li>Methoden/Trigger: <code>ProcessSwPackage</code>, <code>Cancel</code>, <code>Cancelled</code>, <code>PackageProcessed</code>, <code>RevertProcessedSwPackages</code>, <code>Activate</code>, <code>OnSuccess</code>, <code>OnFailure</code>, <code>Rollback</code>, <code>Finish</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Staging & Paketverarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt aus <code>kIdle</code> nach <code>kProcessing</code> via Methodenaufruf <code>ProcessSwPackage</code>.</li>\n<li>Bei Abbruch ohne verarbeitete Pakete (<code>Cancelled [ProcessedPackages=0]</code>) Rückkehr nach <code>kIdle</code>.</li>\n<li>Bei erfolgreichem Abschluss oder Abbruch mit bereits persistierten Teilpaketen (<code>Cancelled, PackageProcessed [ProcessedPackages&gt;0]</code>) Übergang nach <code>kReady</code>.</li>\n<li>Aus <code>kReady</code> können sequenziell weitere Pakete verarbeitet werden (<code>ProcessSwPackage</code> $\\rightarrow$ <code>kProcessing</code> $\\rightarrow$ <code>kReady</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruch vor Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sowohl aus <code>kProcessing</code> als auch aus <code>kReady</code> verwirft <code>RevertProcessedSwPackages</code> alle gepufferten Pakete und wechselt nach <code>kCleaningUp</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung & Verifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>kReady</code> initiiert <code>Activate</code> den Übergang nach <code>kActivating</code>.</li>\n<li>Während <code>kActivating</code> wird <code>DependencyCheck</code> ausgeführt:</li>\n<li>Bei Fehler (<code>OnFailure</code>) fällt das System nicht-destruktiv nach <code>kReady</code> zurück.</li>\n<li>Bei Erfolg (<code>OnSuccess</code>) wechselt das System nach <code>kVerifying</code> (<code>do / MonitorApplicationRestart</code>).</li>\n<li>Aus <code>kVerifying</code>:</li>\n<li>Bei Stabilität (<code>OnSuccess</code>) Übergang nach <code>kActivated</code>.</li>\n<li>Bei Instabilität oder Abbruch: <code>OnFailure</code> oder Methodenaufruf <code>Rollback</code> triggert den Übergang nach <code>kRollingBack</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rollback-Behandlung & Fehlereskalation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>kActivated</code> führt ein <code>Rollback</code>-Aufruf ebenfalls nach <code>kRollingBack</code>.</li>\n<li>In <code>kRollingBack</code> wird <code>roll back to old version</code> ausgeführt:</li>\n<li>Bei erfolgreichem Rollback (<code>OnSuccess</code>) wechselt der Automat nach <code>kRolledBack</code>.</li>\n<li>Schlägt der Rollback-Vorgang fehl (<code>OnFailure</code>), wechselt der Automat in den Fehlerzustand <code>kRollingBackFailed</code>.</li>\n<li>Aus <code>kRollingBackFailed</code> kann über den Methodenaufruf <code>Rollback</code> ein erneuter Rollback-Versuch nach <code>kRollingBack</code> initiiert werden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss & Bereinigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sowohl aus <code>kRolledBack</code> als auch aus <code>kActivated</code> führt der Aufruf <code>Finish</code> nach <code>kCleaningUp</code> (<code>do / clean up</code>).</li>\n<li>Nach Abschluss der Bereinigung führt ein automatischer Übergang zurück in den Ruhezustand <code>kIdle</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Relevanz für Software-Design & Implementierung:</strong></li>\n<li>Der Automat bildet den C++-Status-Enumerations-Typ <code>ara::ucm::pkgmgr::PackageManagerStatusType</code> ab (präfixt mit <code>k</code>).</li>\n<li>Die explizite Behandlung von <code>kRollingBackFailed</code> erzwingt eine Fehlerbehandlungsstrategie für fehlgeschlagene Rollback-Prozesse (z. B. persistente HW-Fehler oder beschädigte Fallback-Partitionen), inklusive Wiederholbarkeit via <code>Rollback</code>.</li>\n<li>Der Übergang von <code>kRollingBack</code> nach <code>kRolledBack</code> erfordert das explizite Event <code>OnSuccess</code>.</li>\n<li>Entwickler müssen sicherstellen, dass Zustände mit internen Do-Aktivitäten (<code>kProcessing</code>, <code>kActivating</code>, <code>kVerifying</code>, <code>kRollingBack</code>, <code>kCleaningUp</code>) asynchron ausgeführt werden und Ereignisse wie <code>OnSuccess</code> / <code>OnFailure</code> deterministisch emittieren.</li>\n</ul>"}], "trans": [{"from": "FIG-32326ea0e9253bbb", "to": "FIG-756595c0fdad7d52", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Zustand <code>kRollingBackFailed</code> eingeführt oberhalb von <code>kRollingBack</code>.</li>\n<li>Neuer Übergang mit Trigger <code>OnFailure</code> von <code>kRollingBack</code> zu <code>kRollingBackFailed</code>.</li>\n<li>Neuer Übergang mit Trigger <code>Rollback</code> von <code>kRollingBackFailed</code> zurück nach <code>kRollingBack</code>.</li>\n<li>Neuer Trigger <code>OnSuccess</code> am Übergang von <code>kRollingBack</code> nach <code>kRolledBack</code>.</li>\n<li>Umbenennung aller Zustände in <code>k&lt;Name&gt;</code>-Notation (C++-Enum-Konvention von AUTOSAR Adaptive):</li>\n<li><code>IDLE</code> $\\rightarrow$ <code>kIdle</code></li>\n<li><code>PROCESSING</code> $\\rightarrow$ <code>kProcessing</code></li>\n<li><code>READY</code> $\\rightarrow$ <code>kReady</code></li>\n<li><code>ACTIVATING</code> $\\rightarrow$ <code>kActivating</code></li>\n<li><code>VERIFYING</code> $\\rightarrow$ <code>kVerifying</code></li>\n<li><code>ACTIVATED</code> $\\rightarrow$ <code>kActivated</code></li>\n<li><code>ROLLING-BACK</code> $\\rightarrow$ <code>kRollingBack</code></li>\n<li><code>ROLLED-BACK</code> $\\rightarrow$ <code>kRolledBack</code></li>\n<li><code>CLEANING_UP</code> $\\rightarrow$ <code>kCleaningUp</code></li>\n</ul>"}]};
